t. 29, III, da LRF."},{"id":2826,"materia":"afo","nivel":3,"enunciado":"O princípio da não afetação da receita de impostos admite exceção para:","opcoes":["Recursos destinados à saúde e à educação","Pagamento de juros","Publicidade oficial","Compra de veículos"],"explicacao":"Art. 167, IV, da CF."},{"id":2827,"materia":"gest","nivel":1,"enunciado":"Na liderança situacional, para liderados com baixa maturidade, o estilo indicado é:","opcoes":["Determinar","Delegar","Compartilhar","Apenas apoiar"],"explicacao":"Alta tarefa e baixo relacionamento."},{"id":2828,"materia":"gest","nivel":1,"enunciado":"A cultura organizacional é:","opcoes":["O conjunto de valores, crenças e hábitos compartilhados","O organograma formal com cargos e chefias","O orçamento anual","O manual de cargos"],"explicacao":"Ela orienta o comportamento “como as coisas são feitas aqui”."},{"id":2829,"materia":"gest","nivel":2,"enunciado":"O clima organizacional mede:","opcoes":["A percepção das pessoas sobre o ambiente de trabalho","O lucro da empresa","A temperatura das salas","O número de clientes"],"explicacao":"É mais passageiro que a cultura."},{"id":2830,"materia":"gest","nivel":2,"enunciado":"A matriz BCG classifica produtos em:","opcoes":["Estrela, vaca leiteira, interrogação e abacaxi","Forças, fraquezas, oportunidades e ameaças do ambiente","Urgente e importante","Fixos e variáveis"],"explicacao":"Cruza crescimento do mercado e participação."},{"id":2831,"materia":"gest","nivel":3,"enunciado":"Na espiral do conhecimento de Nonaka e Takeuchi, transformar conhecimento tácito em explícito é a:","opcoes":["Externalização","Socialização","Combinação","Internalização"],"explicacao":"Ex.: documentar a experiência de um servidor."},{"id":2832,"materia":"gest","nivel":3,"enunciado":"Pela Lei 14.129/2021, o governo como plataforma significa:","opcoes":["Oferecer dados e serviços abertos para uso da sociedade","Fechar os sistemas públicos ao acesso de terceiros","Contratar só empresas estrangeiras","Acabar com o atendimento presencial"],"explicacao":"Favorece que outros criem soluções com dados públicos."},{"id":2833,"materia":"arq","nivel":1,"enunciado":"A cópia de segurança de um acervo microfilmado deve ser guardada:","opcoes":["Em local diferente do original","Junto do original","No arquivo corrente","Na mesa do chefe"],"explicacao":"Evita perder tudo num mesmo sinistro."},{"id":2834,"materia":"arq","nivel":1,"enunciado":"Em arquivologia, o processo administrativo é um tipo de:","opcoes":["Unidade documental","Fundo","Arranjo","Instrumento de pesquisa"],"explicacao":"Assim como o dossiê."},{"id":2835,"materia":"arq","nivel":2,"enunciado":"O documento recebido de outro órgão, para quem o recebeu, é:","opcoes":["Também documento de arquivo","Documento sem valor","Documento pessoal","Documento de biblioteca sem valor de prova"],"explicacao":"Arquivo inclui documentos produzidos e recebidos."},{"id":2836,"materia":"arq","nivel":2,"enunciado":"A tabela de temporalidade é aplicada, sobretudo, aos documentos nas fases:","opcoes":["Corrente e intermediária","Somente permanente","Somente de criação","Posterior à eliminação"],"explicacao":"Ela define guarda e destino antes do permanente."},{"id":2837,"materia":"arq","nivel":3,"enunciado":"Pela LAI, informações sobre violações de direitos humanos praticadas por agentes públicos:","opcoes":["Não podem ter acesso restrito","São sempre ultrassecretas","Ficam restritas por 100 anos, como dados pessoais","Só a polícia pode consultar"],"explicacao":"Art. 21, parágrafo único, da Lei 12.527/2011."},{"id":2838,"materia":"arq","nivel":3,"enunciado":"O documento arquivístico digital deve ser mantido em ambiente que garanta, ao longo do tempo:","opcoes":["Autenticidade, integridade e acesso","Apenas velocidade","Apenas baixo custo","Apenas cópia em papel"],"explicacao":"É a lógica dos repositórios confiáveis."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select nivel, count(*) as questoes from public.questoes group by nivel order by nivel;
